CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(new.raw_app_meta_data->>'alta_encargado','') <> 'true' THEN RAISE EXCEPTION 'Altas públicas deshabilitadas'; END IF; INSERT INTO public.profiles(id,username,nombre) VALUES(new.id,split_part(new.email,'@',1),coalesce(new.raw_user_meta_data->>'nombre',split_part(new.email,'@',1))); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'user'); RETURN new; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS profiles_username_unique ON public.profiles(username);
CREATE OR REPLACE FUNCTION public.edit_employee(_id uuid,_nombre text,_username text,_activo boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Solo encargado'; END IF; IF _id IS NULL OR _nombre IS NULL OR _username IS NULL OR _activo IS NULL THEN RAISE EXCEPTION 'Datos obligatorios'; END IF; IF _id=auth.uid() AND NOT _activo THEN RAISE EXCEPTION 'No puede desactivarse'; END IF; IF length(trim(_nombre)) NOT BETWEEN 1 AND 100 OR _username !~ '^[a-z0-9._-]{3,40}$' THEN RAISE EXCEPTION 'Datos inválidos'; END IF; UPDATE public.profiles SET nombre=trim(_nombre),username=_username,activo=_activo WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Trabajador inexistente'; END IF; UPDATE auth.users SET email=_username||'@fichaje.local' WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Acceso inexistente'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.decide_correction(_id uuid,_aprobar boolean,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s solicitudes_correccion; BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Solo encargado'; END IF; IF _id IS NULL OR _aprobar IS NULL OR _motivo IS NULL OR length(trim(_motivo))<1 THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF; SELECT * INTO s FROM solicitudes_correccion WHERE id=_id FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud inexistente'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(s.user_id::text,0)); IF EXISTS(SELECT 1 FROM decisiones_correccion WHERE solicitud_id=_id) THEN RAISE EXCEPTION 'Ya decidida'; END IF; INSERT INTO decisiones_correccion(solicitud_id,aprobada,decidida_por,motivo) VALUES(_id,_aprobar,auth.uid(),trim(_motivo)); IF _aprobar THEN PERFORM public.validate_punch_sequence(s.user_id); END IF; END $$;
CREATE OR REPLACE FUNCTION public.validate_punch_sequence(_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e record; st text='fuera'; prev timestamptz; BEGIN FOR e IN SELECT * FROM public.effective_punches(_uid) LOOP IF e.tipo IS NULL OR e.at IS NULL OR e.tipo NOT IN ('entrada','pausa','reanudar','salida') THEN RAISE EXCEPTION 'Fichaje inválido'; END IF; IF prev IS NOT NULL AND e.at<=prev THEN RAISE EXCEPTION 'Las horas deben ser distintas y crecientes'; END IF; IF NOT ((st='fuera' AND e.tipo='entrada') OR (st='trabajando' AND e.tipo IN ('pausa','salida')) OR (st='pausa' AND e.tipo IN ('reanudar','salida'))) THEN RAISE EXCEPTION 'Secuencia de fichajes inválida'; END IF; st=CASE e.tipo WHEN 'entrada' THEN 'trabajando' WHEN 'reanudar' THEN 'trabajando' WHEN 'pausa' THEN 'pausa' ELSE 'fuera' END; prev=e.at; END LOOP; END $$;